export const SOURCES={kp:'https://services.swpc.noaa.gov/products/noaa-planetary-k-index.json',aurora:'https://services.swpc.noaa.gov/json/ovation_aurora_latest.json'};
const utc=s=>Date.parse(/Z$|[+-]\d\d:\d\d$/.test(s)?s:s+'Z');
export function normalizeKp(raw){if(!Array.isArray(raw))throw Error('Formato Kp inválido');let rows=raw;if(Array.isArray(raw[0])){const keys=raw[0];rows=raw.slice(1).map(r=>Object.fromEntries(keys.map((k,i)=>[k,r[i]])));}const result=rows.filter(r=>r.Kp!==null&&r.Kp!==undefined&&r.Kp!=='').map(r=>({time:utc(r.time_tag),kp:Number(r.Kp)})).filter(r=>Number.isFinite(r.time)&&Number.isFinite(r.kp)&&r.kp>=0&&r.kp<=9);return [...new Map(result.map(r=>[r.time,r])).values()].sort((a,b)=>a.time-b.time);}
export function storm(kp){return kp>=9?'G5 · extrema':kp>=8?'G4 · severa':kp>=7?'G3 · forte':kp>=6?'G2 · moderada':kp>=5?'G1 · menor':'Abaixo de G1';}
export function buildReport(kpRaw,auroraRaw,now=Date.now(),errors=[]){
 const start=now-86400000,all=kpRaw?normalizeKp(kpRaw):[],rows=all.filter(r=>r.time>=start&&r.time<=now),latest=rows.at(-1),max=rows.length?Math.max(...rows.map(r=>r.kp)):null,mean=rows.length?rows.reduce((s,r)=>s+r.kp,0)/rows.length:null;
 const stale=!latest||now-latest.time>21600000,coverage=rows.length>=8&&!stale?'8 ou mais estimativas na janela':'Cobertura parcial ou indisponível';
 let aurora=null;
 if(auroraRaw){const observation=utc(auroraRaw['Observation Time']??''),forecast=utc(auroraRaw['Forecast Time']??'');const coords=Array.isArray(auroraRaw.coordinates)?auroraRaw.coordinates.filter(p=>Array.isArray(p)&&p.length>=3&&p.every(Number.isFinite)&&p[0]>=0&&p[0]<=360&&p[1]>=-90&&p[1]<=90&&p[2]>=0&&p[2]<=100):[];if(Number.isFinite(observation)&&Number.isFinite(forecast)&&coords.length){aurora={observation:new Date(observation).toISOString(),forecast:new Date(forecast).toISOString(),stale:now-observation>10800000||observation>now+3600000,coordinates:coords.filter(p=>p[2]>=1)};}else errors=[...errors,'Formato do modelo de aurora indisponível.'];}
 let summary=rows.length?`Nas últimas 24 horas consultadas, o Kp estimado chegou a ${max.toFixed(2).replace('.',',')} (${storm(max)}). A média das ${rows.length} estimativas disponíveis foi ${mean.toFixed(2).replace('.',',')}. ${max>=5?'Houve estimativas no nível de tempestade geomagnética; isso indica atividade planetária elevada, sem localizar efeitos em uma cidade específica.':'As estimativas disponíveis ficaram abaixo do limiar de tempestade geomagnética G1.'}`:'Não há estimativas Kp válidas nas últimas 24 horas. Não é possível concluir se a atividade esteve baixa ou elevada.';
 if(stale&&rows.length)summary+=' A última estimativa está atrasada; este resumo não descreve as condições atuais.';
 if(rows.length<8&&rows.length)summary+=' A cobertura da janela é parcial.';
 summary+=' O mapa de aurora é uma previsão de curto prazo capturada na consulta, não um registro de ocorrências ao longo de todo o dia. As grades da crosta e da gravidade são referências estáticas, sem detecção diária de novas anomalias.';
 return {collectedAt:new Date(now).toISOString(),windowStart:new Date(start).toISOString(),windowEnd:new Date(now).toISOString(),rows,max,mean,latest:latest??null,stale,coverage,summary,aurora,errors,sources:SOURCES};
}
export async function collectReport(){const now=Date.now(),results=await Promise.allSettled(Object.values(SOURCES).map(async url=>{const r=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('HTTP '+r.status);return r.json();}));const errors=results.flatMap((r,i)=>r.status==='rejected'?[`${i===0?'Kp':'Aurora'}: fonte indisponível.`]:[]);return buildReport(results[0].status==='fulfilled'?results[0].value:null,results[1].status==='fulfilled'?results[1].value:null,now,errors);}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function auroraSvg(report,land){const a=report.aurora,W=1000,H=500,top=80,left=50,fx=lon=>left+(lon+180)/360*W,fy=lat=>top+(90-lat)/180*H;let parts=[`<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="680" viewBox="0 0 1100 680"><rect width="1100" height="680" fill="#101b2b"/><g font-family="sans-serif" fill="#eff7fc"><text x="50" y="34" font-size="23">MagneTerra · previsão de aurora OVATION</text><text x="50" y="58" font-size="13">${a?'Previsão: '+esc(a.forecast)+' · observação de entrada: '+esc(a.observation):'Dados de aurora indisponíveis'}</text></g><rect x="50" y="80" width="1000" height="500" fill="#142b3d"/>`];
 for(const f of land?.features??[]){const polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[];for(const poly of polys){const d=poly.map(ring=>ring.map(([x,y],i)=>(i?'L':'M')+fx(x).toFixed(1)+','+fy(y).toFixed(1)).join(' ')+'Z').join(' ');parts.push(`<path d="${d}" fill="#415466" stroke="#6c7b89" stroke-width=".5" fill-rule="evenodd"/>`);}}
 if(a&&!a.stale)for(const [lon,lat,p] of a.coordinates){if(p<5)continue;const x=lon>180?lon-360:lon;const t=p/100;parts.push(`<rect x="${fx(x-.5).toFixed(1)}" y="${fy(lat+.5).toFixed(1)}" width="2.9" height="2.9" fill="rgb(${Math.round(80+175*t)},${Math.round(210-100*t)},90)" opacity="${(.3+.6*t).toFixed(2)}"/>`);}
 for(let lat=-60;lat<=60;lat+=30)parts.push(`<path d="M50 ${fy(lat)}H1050" stroke="#96acba" opacity=".25"/><text x="8" y="${fy(lat)+4}" fill="#b9cbd8" font-family="sans-serif" font-size="12">${lat}°</text>`);
 for(let lon=-180;lon<=180;lon+=60)parts.push(`<path d="M${fx(lon)} 80V580" stroke="#96acba" opacity=".25"/><text x="${fx(lon)-13}" y="601" fill="#b9cbd8" font-family="sans-serif" font-size="12">${lon}°</text>`);
 if(!a||a.stale)parts.push(`<text x="550" y="320" text-anchor="middle" fill="white" font-size="22" font-family="sans-serif">${a?'Previsão desatualizada — não exibida como atual':'Mapa indisponível nesta consulta'}</text>`);
 parts.push(`<g fill="#cedce6" font-family="sans-serif" font-size="13"><text x="50" y="632">Probabilidade estimada de aurora: verde (5%) → amarelo/vermelho (100%). Valores menores que 5% omitidos.</text><text x="50" y="656">NOAA SWPC / OVATION · costas: Natural Earth · previsão de curto prazo, não mapa de anomalias da crosta.</text></g></svg>`);return parts.join('');}
export function kpSvg(report){const W=1000,H=230,start=Date.parse(report.windowStart),end=Date.parse(report.windowEnd);let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 340"><rect width="1100" height="340" fill="#f2f6fa"/><text x="50" y="30" font-family="sans-serif" font-size="20" fill="#16344c">Kp planetário estimado · janela de 24 horas (UTC)</text>`;for(let v=0;v<=9;v+=1){const y=60+H-v/9*H;s+=`<path d="M50 ${y}H1050" stroke="${v===5?'#bb6044':'#dce4ec'}"/><text x="25" y="${y+4}" font-family="sans-serif" font-size="12">${v}</text>`;}for(const r of report.rows){const x=50+(r.time-start)/(end-start)*W,y=60+H-r.kp/9*H;s+=`<rect x="${x}" y="${y}" width="${Math.max(0,Math.min(80,1050-x))}" height="${Math.max(1,H*r.kp/9)}" fill="${r.kp>=5?'#ba523e':'#008669'}"/><text x="${x}" y="${y-6}" font-family="sans-serif" font-size="12">${r.kp.toFixed(2)}</text>`;}s+=`<text x="50" y="319" font-family="sans-serif" font-size="12">${esc(report.windowStart)} → ${esc(report.windowEnd)} · NOAA SWPC · G1 a partir de Kp 5</text></svg>`;return s;}
